// [v6.8 D1] Recupere les positions geocentriques (Moshier) des planetes le jour de chaque
// evenement, via le noeud Scan Transits (HTTP /transits?date_debut=X&date_fin=Y).
// Retourne un array [{date:'YYYY-MM-DD', planetes:{Saturne:{longitude_absolue,...}, ...}}, ...]
// Mode defensif : si le noeud n'existe pas (ancien workflow), transitsByDate reste vide et
// transitScore = 0 -> pas de regression. Critique externe valide : transit lourd planete lente
// sur ASC/MC/DSC/IC est le declencheur temporel le plus precis (1° = 4 min de naissance).
let transitsByDate={};
try{
  const tItems=$('Scan Transits').all();
  if(tItems&&tItems.length>0){
    // Mode N items : chaque item correspond a une date d'evenement, et son json est soit
    // - un array (reponse brute /transits) [{date, planetes}]
    // - un objet enveloppe avec data/items
    // - un objet error (HTTP 500 etc.)
    for(const it of tItems){
      let v=it&&it.json;
      if(!v)continue;
      if(v.error)continue;
      let arr=v;
      if(!Array.isArray(arr)){
        if(arr.data&&Array.isArray(arr.data))arr=arr.data;
        else if(typeof arr==='object'){
          const vals=Object.values(arr);
          if(vals.length>0&&vals[0]&&vals[0].date)arr=vals;
          else arr=[arr];
        }
      }
      if(Array.isArray(arr)){
        for(const day of arr){
          if(day&&day.date&&day.planetes)transitsByDate[day.date]=day.planetes;
        }
      }
    }
  }
