const M1_PLANET_WEIGHT={
  'Soleil':3,'Sun':3,
  'Lune':3,'Moon':3,
  'Mercure':2,'Mercury':2,
  'V\u00e9nus':2,'Venus':2,
  'Mars':2,
  'Jupiter':1.5,
  'Saturne':1.5,'Saturn':1.5,
  'Uranus':1,
  'Neptune':1,
  'Pluton':1,'Pluto':1,
  'Chiron':0.8
