function affinityBonus(evtType,targetName){
  if(!evtType)return 1;
  const a=EVT_AFFINITY[evtType];
  if(!a)return 1;
  if((a.p||[]).includes(targetName))return AFFINITY_BONUS;
  if((a.a||[]).includes(targetName))return AFFINITY_BONUS;
  return 1;
}
function affinityBonusArcProg(evtType,targetName){
  if(!evtType||!targetName)return 1;
  const a=EVT_AFFINITY[evtType];
  if(!a)return 1;
  if((a.p||[]).includes(targetName))return AFFINITY_ARC_PROG;
  if((a.a||[]).includes(targetName))return AFFINITY_ARC_PROG;
  return 1;
}

function normDeg(d){return((d%360)+360)%360}
function aspDist(a,b){const d=Math.abs(normDeg(a)-normDeg(b));return Math.min(d,360-d)}

// [v6.6 D5] Suppression des aspects mineurs qnx (quinconce 150°) et ssx (demi-sextile 30°).
// Critique externe valide : en rectification, les evenements majeurs reagissent quasi exclusivement
// aux aspects ptolemaiques (conj/opp/car/tri/sex). qnx/ssx ajoutent du bruit sans signal fiable.
// [v6.7 D3 - rejete] Test orb 1.5 -> 1.0 + SR 3.0 -> 1.5 : bench 16 cas neutre 4/16, mais
// score absolu chute (Bardot 73.9->58.3) et perte DG (15.28->9.80 puis perte top-1). Casse
// autant de signaux legitimes qu'il discrimine. Restauration orb 1.5 / SR 3.0.
const ASPECTS=[
  {name:'conj',angle:0,orb:1.5,weight:4},
  {name:'opp',angle:180,orb:1.5,weight:3},
  {name:'car',angle:90,orb:1.5,weight:2},
  {name:'tri',angle:120,orb:1.5,weight:1},
  {name:'sex',angle:60,orb:1.5,weight:1}
];

const PW={'Soleil':1.5,'Sun':1.5,'Lune':1.5,'Moon':1.5,'Mercure':1.5,'Mercury':1.5,'V\u00e9nus':1.5,'Venus':1.5,'Mars':1.5,'Jupiter':1.0,'Saturne':1.0,'Saturn':1.0,'Uranus':1.0,'Neptune':1.0,'Pluton':1.0,'Pluto':1.0,'Ascendant':2.0,'Descendant':2.0,'Milieu du Ciel':2.0,'MC':2.0,'Imum Coeli':2.0,'IC':2.0};
function pw(n){return PW[n]||0.5;}
function bestAspect(pos1,pos2,orbOvr){
  const d=aspDist(pos1,pos2);
  for(const asp of ASPECTS){const ou=orbOvr||asp.orb;const ao=Math.abs(d-asp.angle);if(ao<ou)return{name:asp.name,angle:asp.angle,weight:asp.weight,ao:ao,ou:ou};}
  return null;
}


function sunLong(jd){
  const T=(jd-2451545.0)/36525.0;
  const L0=280.46646+36000.76983*T+0.0003032*T*T;
  const Mr=(357.52911+35999.05029*T-0.0001537*T*T)*R;
  const C=(1.9146-0.004817*T)*Math.sin(Mr)+0.019993*Math.sin(2*Mr)+0.00029*Math.sin(3*Mr);
  return((L0+C)%360+360)%360;
}
function jdFull(y,m,d,h){return jd0(y,m,d)+(h||0)/24;}
function findSRjd(nSDeg,eY,bm,bd){
  let lo=jdFull(eY,bm,bd,0)-1.5,hi=jdFull(eY,bm,bd,0)+1.5;
  for(let i=0;i<25;i++){
    const mid=(lo+hi)/2;
    let diff=sunLong(mid)-nSDeg;
    if(diff>180)diff-=360;if(diff<-180)diff+=360;
    if(diff>0)hi=mid;else lo=mid;
  }
  return(lo+hi)/2;
}
function calcASCjd(jd){
  const T=(jd-2451545.0)/36525.0;
  let gmst=280.46061837+360.98564736629*(jd-2451545.0)+0.000387933*T*T;
  gmst=((gmst%360)+360)%360;
  const lst=((gmst+lon)%360+360)%360;
  const eps=(23.4393-0.013*T)*R;const A=lst*R,L=lat*R;
  return((Math.atan2(-Math.cos(A),Math.sin(A)*Math.cos(eps)+Math.tan(L)*Math.sin(eps))/R+180)%360+360)%360;
}
function calcMCjd(jd){
  const T=(jd-2451545.0)/36525.0;
  let gmst=280.46061837+360.98564736629*(jd-2451545.0)+0.000387933*T*T;
  gmst=((gmst%360)+360)%360;
  const lst=((gmst+lon)%360+360)%360;
  const eps=(23.4393-0.013*T)*R;const A=lst*R;
  return((Math.atan2(Math.sin(A),Math.cos(A)*Math.cos(eps))/R)%360+360)%360;
}

// [v8.2 fix] Normalisation des noms de signes : l'API renvoie "Gemeaux"/"Belier" avec
// accent, le scorer interne (sgn ligne 61) utilise sans accent. Selon la source (API
// vs math fallback), le meme signe avait 2 orthographes -> 2 groupes distincts dans
// signGroupsForMean -> ranking "Gemeaux" et "Gemeaux" en doublon. On strip les accents
// a la source pour aligner sur la convention interne.
function _stripAccents(s){return s==null?s:String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function getFromHouses(hItem){
  if(!hItem?.json)return null;const j=hItem.json;
  if(j.output&&Array.isArray(j.output)){
    const h1=j.output.find(h=>h.house===1||h.house_number===1);
    const h10=j.output.find(h=>h.house===10||h.house_number===10);
    return{ascDeg:h1?.fullDegree,mcDeg:h10?.fullDegree,ascSign:_stripAccents(h1?.zodiac_sign?.name?.fr)};
  }
  if(j.ascendant)return{ascDeg:j.ascendant.fullDegree,mcDeg:j.mc?.fullDegree||j.midheaven?.fullDegree,ascSign:_stripAccents(j.ascendant.zodiac_sign?.name?.fr)};
  return null;
}
function getFromPlanets(pItem){
  if(!pItem?.json?.output||!Array.isArray(pItem.json.output))return null;
  const asc=pItem.json.output.find(p=>p.planet?.fr==='Ascendant'||p.planet?.en==='Ascendant');
  const mc=pItem.json.output.find(p=>p.planet?.fr==='Milieu du Ciel'||p.planet?.en==='MC');
  if(!asc)return null;
  return{ascDeg:asc.fullDegree,mcDeg:mc?.fullDegree,ascSign:_stripAccents(asc.zodiac_sign?.name?.fr)};
}

// N8N aplatit la reponse [{data:[{date,planetes},...]}] en items individuels
// progSlice = tableau d'items n8n pour UN creneau candidat
// Vitesse progresse: Lune=rapide, perso=normal, lentes=faible
const PS={'Lune':1.5,'Soleil':1.0,'Mercure':1.0,'V\u00e9nus':1.0,'Mars':0.7,'Jupiter':0.3,'Saturne':0.3,'Uranus':0.15,'Neptune':0.15,'Pluton':0.15};
function ps(n){return PS[n]||0.5;}

function countProgHits(progSlice,slotAsc,slotMc,targets,slotJD){
  if(!progSlice||progSlice.length===0)return{score:0,details:[]};
  const data=progSlice.map(it=>it.json).filter(d=>d&&d.planetes&&d.date);
  if(data.length===0)return{score:0,details:[]};
  let score=0;const details=[];const seen=new Set();
  function toDecDate(d){const p=d.split('-');return parseInt(p[0])+((parseInt(p[1])-1)*30.44+parseInt(p[2]))/365.25;}
  const progPlanets=['Soleil','Lune','Mars','Mercure','Jupiter','V\u00e9nus','Saturne','Uranus','Neptune','Pluton'];
  for(const evt of events){
    const evtDec=evt.year+((evt.month-1)*30.44+evt.day)/365.25;
    let closest=data[0],minDist=999;
    for(const d of data){const dd=toDecDate(d.date);if(Math.abs(dd-evtDec)<minDist){minDist=Math.abs(dd-evtDec);closest=d;}}
    if(!closest?.planetes)continue;
    const pp=closest.planetes;
    // [P-detangles v5.6] Recalcul LOCAL des angles progress\u00e9s pAsc/pMc pour CE cr\u00e9neau et CET \u00e9v\u00e9nement.
    // Avant : on prenait pp['Ascendant'] / pp['MC'] de l'API, calcul\u00e9s pour une heure de naissance unique
    // (milieu de plage), donc identiques pour tous les slots du scan et faux pour les slots loin du milieu.
    // Maintenant : progression secondaire = jour-pour-an. L'instant progress\u00e9 = naissance candidate + age (j).
    // pAsc/pMc d\u00e9pendent fortement de l'heure de naissance candidate (~15\u00b0/h), pAsc = ASC sid\u00e9ral \u00e0 l'instant
    // birthCand + age. Les plan\u00e8tes progress\u00e9es (Lune, etc.) restent prises de l'API, ~insensibles \u00e0 l'heure.
    let pAscLocal,pMcLocal;
    if(slotJD!==undefined){
      const ageY=evtDec-birthDecimal;
      const progJD=slotJD+ageY;
      pAscLocal=calcASCjd(progJD);
      pMcLocal=calcMCjd(progJD);
    }
    // [P8 v5.2] Pour les progressions, le bonus d'affinité s'applique sur la PLANÈTE PROGRESSÉE
    // (la "source" qui transporte la sémantique de l'événement). Ex : voyage_important + pJupiter ↔ nXxx ⇒ ×1.5.
    if(slotAsc!==undefined){
      for(const pn of progPlanets){
        if(!pp[pn])continue;
        const ab=affinityBonusArcProg(evt.type,pn);
        const asp=bestAspect(pp[pn].longitude_absolue,slotAsc,1.0);
        if(asp){
          const key='p'+pn+'_'+asp.name+'_nASC';
          const dup=seen.has(key);if(!dup)seen.add(key);
          const tight=1-asp.ao/asp.ou;
          let w=Math.round(asp.weight*pw(pn)*ps(pn)*tight*(dup?0.25:1)*10)/10;
          if(ab>1)w=Math.round(w*ab*10)/10;
          if(w>=0.3){score+=w;details.push(evt.label+': p'+pn+' '+asp.name+' nASC ('+w.toFixed(1)+' '+asp.ao.toFixed(2)+'\u00B0'+(dup?'*':'')+(ab>1?' \u2295':'')+')');
          }
        }
      }
    }
    if(slotMc!==undefined){
      for(const pn of progPlanets){
        if(!pp[pn])continue;
        const ab=affinityBonusArcProg(evt.type,pn);
        const asp=bestAspect(pp[pn].longitude_absolue,slotMc,1.0);
        if(asp){
          const key='p'+pn+'_'+asp.name+'_nMC';
          const dup=seen.has(key);if(!dup)seen.add(key);
          const tight=1-asp.ao/asp.ou;
          let w=Math.round(asp.weight*pw(pn)*ps(pn)*tight*(dup?0.25:1)*10)/10;
          if(ab>1)w=Math.round(w*ab*10)/10;
          if(w>=0.3){score+=w;details.push(evt.label+': p'+pn+' '+asp.name+' nMC ('+w.toFixed(1)+' '+asp.ao.toFixed(2)+'\u00B0'+(dup?'*':'')+(ab>1?' \u2295':'')+')');
          }
        }
      }
    }
    // [P-detangles v5.6] Priorit\u00e9 : valeur locale recalcul\u00e9e par cr\u00e9neau ; fallback API si slotJD indisponible.
    const pAsc=(pAscLocal!==undefined)?pAscLocal:pp['Ascendant']?.longitude_absolue;
    const pMc=(pMcLocal!==undefined)?pMcLocal:pp['MC']?.longitude_absolue;
    // [P-circular-asp v5.1] Pénalité pour les aspects "auto-référents" entre angle progressé et angle natal.
    // pASC↔nASC, pASC↔nMC, pMC↔nASC, pMC↔nMC (et leurs équivalents DSC/IC) sont mathématiquement
    // sur-exprimés au slot candidat car n* dépend du slot et p* en est quasi indépendant : trouver une
    // conjonction parfaite revient à résoudre l'équation auto-référente, pas à valider une info externe.
    const CIRC_PEN=0.2;
    // [P8 v5.2] Pour pASC↔np / pMC↔np, le bonus s'applique sur la CIBLE NATALE (np.name)
    // car c'est elle qui porte la sémantique. Le bonus s'empile avec la pénalité circulaire
    // (un voyage_important sur Jupiter natal reste valide même si Jupiter ≠ angle).
    if(pAsc!==undefined){
      for(const np of targets){
        const asp=bestAspect(pAsc,np.deg,1.0);
        if(asp){
          const isCirc=ANGLE_NAMES.includes(np.name);
          const ab=affinityBonusArcProg(evt.type,np.name);
          const key='pASC_'+asp.name+'_n'+np.name;
          const dup=seen.has(key);if(!dup)seen.add(key);
          const tight=1-asp.ao/asp.ou;
          let w=Math.round(asp.weight*pw(np.name)*1.5*tight*(dup?0.25:1)*10)/10;
          if(isCirc)w=Math.round(w*CIRC_PEN*10)/10;
          if(ab>1)w=Math.round(w*ab*10)/10;
          if(w>=0.3){score+=w;details.push(evt.label+': pASC '+asp.name+' n'+np.name+' ('+w.toFixed(1)+' '+asp.ao.toFixed(2)+'\u00B0'+(dup?'*':'')+(isCirc?' \u21BB':'')+(ab>1?' \u2295':'')+')');
          }
        }
      }
    }
    if(pMc!==undefined){
      for(const np of targets){
        const asp=bestAspect(pMc,np.deg,1.0);
        if(asp){
          const isCirc=ANGLE_NAMES.includes(np.name);
          const ab=affinityBonusArcProg(evt.type,np.name);
          const key='pMC_'+asp.name+'_n'+np.name;
          const dup=seen.has(key);if(!dup)seen.add(key);
          const tight=1-asp.ao/asp.ou;
          let w=Math.round(asp.weight*pw(np.name)*tight*(dup?0.25:1)*10)/10;
          if(isCirc)w=Math.round(w*CIRC_PEN*10)/10;
          if(ab>1)w=Math.round(w*ab*10)/10;
          if(w>=0.3){score+=w;details.push(evt.label+': pMC '+asp.name+' n'+np.name+' ('+w.toFixed(1)+' '+asp.ao.toFixed(2)+'\u00B0'+(dup?'*':'')+(isCirc?' \u21BB':'')+(ab>1?' \u2295':'')+')');
          }
        }
      }
    }
  }
  return{score,details};
}
const validProg=progItems.filter(it=>it.json&&it.json.planetes&&it.json.date);
