// [v8.3 NOISE AUDIT] Audit de l'integrite du pairing entre les requetes HTTP paralleles.
// Theorie : si tous les items HTTP ont pairedItem, le DHN est independant de l'ordre
// d'arrivee n8n. Si certains items n'ont pas pairedItem, on tombe sur le fallback
// `housesItems[i]` qui depend de l'ordre d'arrivee -> bruit run-to-run.
function _hashStr(s){
  let h=0;
  const str=String(s||'');
  for(let i=0;i<str.length;i++){h=((h<<5)-h+str.charCodeAt(i))|0;}
  return (h>>>0).toString(16).padStart(8,'0');
}
function _itemsSig(arr,kind){
  const ids=[];
  let pairedCount=0;
  for(const it of (arr||[])){
    const sc=pairedScorerIdx(it);
    if(sc!=null)pairedCount++;
    let key='';
    if(kind==='houses'){
      const j=it?.json;
      if(j?.output&&Array.isArray(j.output)){
        const h1=j.output.find(h=>h.house===1||h.house_number===1);
        key=h1?String(Math.round((h1.fullDegree||0)*1000)/1000):'';
      }else if(j?.ascendant){key=String(Math.round((j.ascendant.fullDegree||0)*1000)/1000);}
    }else if(kind==='planets'){
      const j=it?.json;
      if(j?.output&&Array.isArray(j.output)){
        const asc=j.output.find(p=>p.planet?.fr==='Ascendant'||p.planet?.en==='Ascendant');
        key=asc?String(Math.round((asc.fullDegree||0)*1000)/1000):'';
      }
    }else{
      const j=it?.json||{};
      key=String(j._slotH||'')+':'+String(j._slotM||'');
    }
    ids.push(`${sc==null?'-':sc}:${key}`);
  }
  return {pairedCount,total:arr?.length||0,sigSorted:_hashStr(ids.slice().sort().join('|')),sigOrdered:_hashStr(ids.join('|'))};
}
const _scorerSig=_itemsSig(scorerItems,'scorer');
