    srScore:slot?.srScore!=null?Math.round((slot.srScore||0)*100)/100:null,
    wScore:slot?.wScore!=null?Math.round((slot.wScore||0)*100)/100:null,
    totalScore:slot?.totalScore!=null?Math.round((slot.totalScore||0)*100)/100:null
  };
});

