function T(key, p){
  const dict = isEN ? STR.en : STR.fr;
  let s = dict[key];
  if (s === undefined) s = STR.fr[key] !== undefined ? STR.fr[key] : key;
  if (typeof s !== 'string') return s;
  if (!p) return s;
  return s.replace(/\{(\w+)\}/g, function(_, n){ return (p[n]!==undefined && p[n]!==null) ? String(p[n]) : ''; });
}
function TConfLabel(label){
  const dict = isEN ? STR.en.confLabels : STR.fr.confLabels;
  return dict[label] || label;
}
function THypConf(label){
  const dict = isEN ? STR.en.hypConfLabels : STR.fr.hypConfLabels;
  return dict[label] || label;
}
const picScopeTxt = gridFull ? T('picScopeFull') : T('picScopePartial', { n: nAnalysed });
try{const sm=firstItem._scanMeta?JSON.parse(firstItem._scanMeta):null;if(sm&&sm.slots)scanMetaNote=T('scorerMeta',{x:sm.slots,mode:sm.mode||''});}catch(eM){}
if(_plageRaw){
  if(_plageRaw.ignored){
    plageHtml='<p style="font-size:13px;color:#444">'+T('plageIgnored',{lab:_plageRaw.lab})+'</p>';
  } else {
    plageHtml='<p style="font-size:13px;color:#444">'+T('plageRestricted',{lab:_plageRaw.lab})+'</p>';
  }
}

// [i18n v5.5] Reconstruction de `method` selon la langue (la version FR construite plus haut est écrasée).
if(typeof te !== 'undefined' && te > 0){
  method = T('methodArcsProg', { a: sf(best.arcScore), p: sf(best.progScore), r: sf(best.srScore||0) });
  method += qFactor < 1
    ? T('methodQuestAdj', { w: sf(best.wScore), raw: sf(best.wScoreRaw||0), q: sfq(qFactor) })
    : T('methodQuestRaw', { w: sf(best.wScore) });
} else {
  const w = qFactor < 1 ? T('methodQuestionnaireUsed', { q: sfq(qFactor) }) : '';
  method = T('methodQuestionnaireOnly', { sign: best.wSign||'?', raw: sf(best.wScoreRaw||0), w: w });
}

// [P2 v5.1] Score de confiance. Un seul niveau est désormais publié : le SIGNE (écart
// au 2e signe). Le niveau HEURE reste calculé pour le diagnostic, jamais affiché.
// [Phase 4] Calcul avant le bloc hero pour afficher le badge de confiance global dans l'en-tête.
// [P-confiance v5.7] La fenêtre horaire n'est plus GRADUÉE : demi-largeur fixe et
// mesurée. Trois constats sur les 8 cas AA certifiés du banc (script
// SITE/scripts/_enprat/audit/DHN/dhn-calibre-confiance.mjs) :
//  - la fenêtre graduée (±15 à ±60) ne contenait l'heure vraie que dans 2 cas sur 8 ;
//  - l'écart relatif au 2e créneau ne PRÉDIT PAS l'erreur : r = -0,51 pour un seuil
//    de significativité de 0,71 à n=8, donc dans le bruit. Régler quatre paliers sur
//    8 cas serait du surapprentissage ;
//  - ±45 min couvre 7 cas sur 8 (±40 n'en couvre que 5, ±50 les 8).
// [v9.2] La confiance SIGNE n'est plus GRADUÉE non plus, pour trois raisons mesurées le
// 2026-08-14 sur le banc AVEUGLE (24 h, aucun indice d'heure — l'ancien banc centrait la
// fenêtre sur l'heure vraie et ne laissait que 1 à 3 signes en compétition) :
//  - elle était calculée sur l'écart entre PICS TECHNIQUES, alors que le signe est choisi
//    par le questionnaire (SIGN_FROM_Q_ONLY) : elle notait un classement qui ne décide pas ;
//  - en scan 24 h l'écart relatif entre deux pics de signes voisins reste sous 4 %, donc le
//    grader restait collé au plancher : 7 cas sur 8 affichaient « Très faible », dont les
//    5 cas où le signe trouvé était JUSTE. On sous-vendait un résultat correct ;
//  - aucun indicateur disponible au moment du run ne sépare les justes des faux (marge
//    absolue, marge relative, score absolu, qConvergence : tous chevauchent — cf.
//    scripts/_enprat/audit/DHN/dhn-separabilite-confiance.mjs).
// Chiffres réels du banc aveugle : 5/8 en top-1, 6/8 en top-3. Ils sont désormais annoncés
// tels quels (confSignMeasured), comme la fenêtre horaire l'est depuis _HOUR_BAND_MIN.
// Le label gradué reste CALCULÉ et exporté dans dhnMetrics.confidence pour le diagnostic.
const _HOUR_BAND_MIN=45;
let confLabelGlobal='Inconnue', confColor='#2E1560', confSigneTxt='', confHeureTxt='', confEcartS=null, confEcartH=null, confSigneLabel='Inconnue', confHeureLabel='Inconnue';
// Libellé public du badge. Initialisé hors du try : si le calcul de confiance échoue, le
// mail doit rester lisible plutôt qu'afficher « undefined » sous la fenêtre horaire.
let confBadgeTxt=T('confSignBadge');
try{
  const sortedSig=ascPeaksSorted.map(e=>e[1].totalScore);
  let ecartSrel=null;
  if(sortedSig.length>=2&&sortedSig[0]>0){
    confEcartS=sortedSig[0]-sortedSig[1];
    ecartSrel=confEcartS/sortedSig[0];
    // [v5.8 P1.3] Seuils durcis (benchmark celebs) : écart relatif + cohérence multi-techniques.
    if(ecartSrel>=0.20)confSigneLabel='Forte';
    else if(ecartSrel>=0.10)confSigneLabel='Moyenne';
    else if(ecartSrel>=0.04)confSigneLabel='Faible';
    else confSigneLabel='Très faible';
    const cc=Number(best?.coherenceCount)||0;
    if(cc<2&&(confSigneLabel==='Forte'||confSigneLabel==='Moyenne')){
      confSigneLabel='Faible';
    }
    // [v5.10 Fix B] Désaccord Q fort vs signe prédit → baisse d'un cran (ex. YSL).
    if(qTopSign && qConvergence>=0.30){
      const bestSignNorm=normSignName(best?.wSign||best?.ascSign||'');
      if(bestSignNorm && bestSignNorm!==qTopSign){
        if(confSigneLabel==='Forte')confSigneLabel='Moyenne';
        else if(confSigneLabel==='Moyenne')confSigneLabel='Faible';
      }
    }
  }
  const bestSignKey=best.wSign||best.ascSign||'?';
  const sameSignSlots=validDetail.filter(d=>((d.wSign||d.ascSign||'?')===bestSignKey)).sort((a,b)=>b.totalScore-a.totalScore);
  let ecartHrel=null;
  if(sameSignSlots.length>=2&&sameSignSlots[0].totalScore>0){
    confEcartH=sameSignSlots[0].totalScore-sameSignSlots[1].totalScore;
    ecartHrel=confEcartH/sameSignSlots[0].totalScore;
    // [v5.8 P1.3] Seuils heure (écart relatif au 2e créneau même signe). Conservés
    // pour le DIAGNOSTIC seul (exportés dans `confidence.heure` et lus par le banc
    // d'audit) : ils ne pilotent plus ni le texte client ni la largeur de fenêtre,
    // l'écart relatif ne prédisant pas l'erreur (cf. _HOUR_BAND_MIN).
    if(ecartHrel>=0.08)confHeureLabel='Forte';
    else if(ecartHrel>=0.03)confHeureLabel='Moyenne';
    else if(ecartHrel>=0.01)confHeureLabel='Faible';
    else confHeureLabel='Très faible';
  }
  // Un seul signe candidat sur les créneaux analysés : le signe ne sort pas d'une
  // compétition entre techniques, il est IMPOSÉ par la plage fournie par le client.
  // L'ancien code affichait alors « Inconnue » (badge « — »), ce qui le sous-vendait ;
  // le grader « Très net » le survendrait, puisque rien n'a été discriminé.
  if(sortedSig.length===1)confSigneLabel='Imposée';
  confLabelGlobal=confSigneLabel;
  // Un seul libellé public : « Imposé par la plage » quand la plage a tranché à notre place
  // (information vraie et utile), « Signe estimé » sinon. Plus de gradation ni de code
  // couleur d'alarme : il n'y a rien à graduer (voir en tête de bloc).
  confBadgeTxt = confSigneLabel==='Imposée' ? TConfLabel('Imposée') : T('confSignBadge');
  confColor='#2E1560';
  confSigneTxt = confSigneLabel==='Imposée'
    ? T('confSignForced',{sign:best.ascSign||'?'})
    : T('confSignMeasured',{sign:best.ascSign||'?'});
  // L'heure est annoncée pour ce qu'elle est : une estimation dans une fourchette
  // mesurée, sans note de confiance qui laisserait croire à une précision variable.
  confHeureTxt = T('confTimeFixed',{time:best.time||'?',x:_HOUR_BAND_MIN});
}catch(eConf){}

// [v9.1 UX honnête] L'HEURE est affichée comme une FENÊTRE, pas une fausse minute.
// Mesuré (harnais phaseB 18 cas AA) : la couche horaire la plus informative plafonne
// à ~24 min d'erreur médiane (plateau, jamais un pic ±3 min) ; le SIGNE est le seul
