// DHN — remplace le nœud HTTP « Geocodage » (Nominatim seul).
// Si birth_place_lat / birth_place_lng valides dans Extract → pas d’appel Nominatim.
// Nécessite nœud Code typeVersion ≥ 2.

const v = $input.first().json;

function parseNum(x) {
  if (x === null || x === undefined) return NaN;
  if (typeof x === "number" && Number.isFinite(x)) return x;
  if (typeof x === "string" && String(x).trim()) {
    return parseFloat(String(x).trim().replace(",", "."));
  }
  return NaN;
}

const lat0 = parseNum(v.birth_place_lat);
const lon0 = parseNum(v.birth_place_lng);

if (
  Number.isFinite(lat0) &&
  Number.isFinite(lon0) &&
  Math.abs(lat0) <= 90 &&
  Math.abs(lon0) <= 180
) {
  const disp =
    typeof v.birth_place_formatted_address === "string" && v.birth_place_formatted_address.trim()
      ? v.birth_place_formatted_address.trim()
      : [v.lieu, v.pays].filter(Boolean).join(", ");
  return [{ json: { lat: String(lat0), lon: String(lon0), display_name: disp } }];
}

const lieu = encodeURIComponent((v.lieu || "").trim());
const pays = encodeURIComponent((v.pays || "").trim());
