// Pourquoi : l'API ne sert qu'à fournir les positions des PLANÈTES progressées (Lune, Soleil…),
// qui sont quasi insensibles à l'heure de naissance (≪ 0.1°/h). Les ANGLES progressés (pAsc, pMc),
// eux, varient ≈15°/h et sont désormais recalculés LOCALEMENT par créneau dans countProgHits
// (cf. N8N DHN). Cela rend le score Prog d'un même créneau strictement déterministe et indépendant
// de la plage scannée. Avant : refH = milieu de plage → mêmes coordonnées API utilisées pour tous
// les slots ; pAsc/pMc API = ASC/MC d'une naissance hypothétique au milieu de plage, pas du slot testé.
function gn(n){try{return $(n).first()?.json||null}catch(e){return null}}
const vars=gn('Extract Variables DHN')||gn('Extract Variables DHN1')||gn('Extract Variables');
if(!vars?.date)throw new Error('DHN Build Prog URL : date introuvable.');
const prep=gn('Prepare Timezone')||gn('Prepare Timezone1');
// [P-tz v5.7] Fuseau CORRIGÉ (nœud « TZ Historique ») et non le gmtOffset brut de
// TimezoneDB : sur une naissance de 1890 l'écart atteint 51 min, soit 12,75° d'ASC.
const tzNode=gn('TZ Historique')||gn('TZ Historique1')||gn('Get Timezone')||gn('Get Timezone1');
const lat=parseFloat(prep.lat),lon=parseFloat(prep.lon),tz=(tzNode.gmtOffset||0)/3600;
const dd=vars.date.split('/');
const yr=parseInt(dd[2]),mo=parseInt(dd[1]),da=parseInt(dd[0]);
const refH=12,refM=0;
const evtRaw={...(gn('Evenements de vie')||gn('Evenements de vie1')||{}),...vars};
const evtDates=[];
for(const[k,v]of Object.entries(evtRaw)){
  if(!v||!String(k).startsWith('evt'))continue;
  const allDm=[...String(v).matchAll(/(\d{2})\/(\d{2})\/(\d{4})/g)];
  for(const dm of allDm){evtDates.push({d:parseInt(dm[1]),m:parseInt(dm[2]),y:parseInt(dm[3]),raw:dm[1]+'/'+dm[2]+'/'+dm[3]});}
}
if(evtDates.length===0)return [];
evtDates.sort((a,b)=>(a.y*10000+a.m*100+a.d)-(b.y*10000+b.m*100+b.d));
const dateDebut=evtDates[0].raw;
const dateFin=evtDates[evtDates.length-1].raw;
const url='https://api.spikka.eu/progressions?date_debut='+dateDebut+'&date_fin='+dateFin+'&year='+yr+'&month='+mo+'&date='+da+'&hours='+refH+'&minutes='+refM+'&seconds=0&latitude='+lat+'&longitude='+lon+'&timezone='+tz;
return [{json:{_progUrl:url}}];
